/**
 * @beta
 * 用于缩小声音定义集合的筛选条件。每个字段均为可选，仅当定义时才施加约束；
 * 定义必须满足所有已定义字段才能通过筛选。
 */
export interface SoundDefinitionFilter {
    /**
     * @remarks
     * 要与定义中 music_info.artist 匹配的艺术家名称。比较时忽略大小写。当定义为非空数组时，定义仅在其声明的艺术家匹配提供的某个值时通过。当未定义时，不施加艺术家约束。
     *
     */
    artists?: string[];
    /**
     * @remarks
     * 要与定义中 music_info.genres 匹配的流派。比较时忽略大小写。当定义为非空数组时，定义仅在其声明的至少一个流派匹配提供的某个值时通过。当未定义时，不施加流派约束。
     *
     */
    genres?: string[];
    /**
     * @remarks
     * 以秒为单位的上限（包含）。当定义时，时长较长且未声明时长的定义将被排除。当未定义时，不施加上限。
     *
     */
    maxDuration?: number;
    /**
     * @remarks
     * 以秒为单位的下限（包含）。当定义时，时长较短且未声明时长的定义将被排除。当未定义时，不施加下限。
     *
     */
    minDuration?: number;
    /**
     * @remarks
     * 要与定义中 music_info.moods 匹配的情绪。比较时忽略大小写。当定义为非空数组时，定义仅在其声明的至少一种情绪匹配提供的某个值时通过。当未定义时，不施加情绪约束。
     *
     */
    moods?: string[];
    /**
     * @remarks
     * 要与定义中 tags 匹配的标签约束。标签名称和值的比较均忽略大小写。当定义为非空记录时，对于每个具有非空值数组的条目，仅当标签名称出现在定义中且至少有一个匹配的值时，定义才通过。当未定义时，不施加标签约束。
     *
     */
    tags?: Record<string, string[]>;
    /**
     * @remarks
     * 要与定义中 music_info.title 匹配的标题。比较时忽略大小写。当定义为非空数组时，定义仅在其声明的标题匹配提供的某个值时通过。当未定义时，不施加标题约束。
     *
     */
    titles?: string[];
}